VALUES ('zou-r1', '挟', ARRAY[]::text[], '曹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '曹姓邾国传统世系所列的始封君。通行说将其受封置于周初；之后相传历非、成、车辅、将新、訾父至武公。早期世系据后世文献辑成，具体在位年及部分世系真实性尚不能确证。', '[{"label":"邾国君主世系与传世文献考","url":"https://zh.wikipedia.org/wiki/邾国"},{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"}]'::jsonb, NULL, NULL, '邾子挟')
