VALUES ('zou-r2', '非', ARRAY[]::text[], '曹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '传统邾国世系称其为挟之子、继为国君，后传位于成。此世系见后世文献汇编，未见可据以确定其在位年份的同期纪年。', '[{"label":"邾国君主世系与传世文献考","url":"https://zh.wikipedia.org/wiki/邾国"},{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"}]'::jsonb, NULL, NULL, '邾子非')
