VALUES ('zou-r3', '成', ARRAY[]::text[], '曹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '传统邾国世系称其承继曹非，后传位于车辅；具体在位年代无同期纪年可考，早期世系仍有文献可靠性争议。', '[{"label":"邾国君主世系与传世文献考","url":"https://zh.wikipedia.org/wiki/邾国"},{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"}]'::jsonb, NULL, NULL, '邾子成')
