VALUES ('zou-r4', '车辅', ARRAY[]::text[], '曹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '传统邾国世系列为曹成之后、将新之前的国君；其个人事迹与在位年份未见同期纪年记载。', '[{"label":"邾国君主世系与传世文献考","url":"https://zh.wikipedia.org/wiki/邾国"},{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"}]'::jsonb, NULL, NULL, '邾子车辅')
