VALUES ('zou-r6', '訾父', ARRAY[]::text[], '曹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '传统邾国世系列为将新之后、武公之前的国君；与武公的父子关系见后世世系整理，具体在位年份无同期纪年可考。', '[{"label":"邾国君主世系与传世文献考","url":"https://zh.wikipedia.org/wiki/邾国"},{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"}]'::jsonb, NULL, NULL, '邾子訾父')
