VALUES ('zou-r7', '夷父', ARRAY[]::text[], '曹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '《公羊传》追述邾娄颜（传统系于武公）及叔术、夏父之间的继承与让国故事；传统年表以周宣王诛颜之年系其卒于前796年。故事中的人物身份与世系细节属于传世叙述。', '[{"label":"《春秋公羊传·昭公三十一年》","url":"https://ctext.org/gongyang-zhuan/zhao-gong-san-shi-yi-nian/zhs"},{"label":"邾国君主世系与传世文献考","url":"https://zh.wikipedia.org/wiki/邾国"},{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"}]'::jsonb, '武公', NULL, '邾武公')
