VALUES ('zou-r8', '叔术', ARRAY[]::text[], '曹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '《公羊传》称叔术受周天子命立为邾君，后让位于夏父，并分得滥地；传文以此称许其让国。传统年表系其在位于前795—前781年，起讫年依年表而非传文精确年月。', '[{"label":"《春秋公羊传·昭公三十一年》","url":"https://ctext.org/gongyang-zhuan/zhao-gong-san-shi-yi-nian/zhs"},{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"}]'::jsonb, NULL, NULL, '邾子叔术')
