VALUES ('zou-r9', '夏父', ARRAY[]::text[], '曹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '传统世系称夏父为武公之子；《公羊传》记叔术让国于夏父并以滥地分封。其确切卒年及之后继位年份没有直接纪年证据。', '[{"label":"《春秋公羊传·昭公三十一年》","url":"https://ctext.org/gongyang-zhuan/zhao-gong-san-shi-yi-nian/zhs"},{"label":"邾国君主世系与传世文献考","url":"https://zh.wikipedia.org/wiki/邾国"},{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"}]'::jsonb, NULL, NULL, '邾子夏父')
