VALUES ('zou-r12', '琐', ARRAY[]::text[], '曹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '邾宪公，克之子。传统年表系其在位于前677—前666年，后由邾文公继位；早期君主个人事迹记载较少。', '[{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"},{"label":"邾国君主世系图（列作琐）","url":"https://zh.wikipedia.org/wiki/邾國君主世系圖"},{"label":"邾宪公","url":"https://zh.wikipedia.org/wiki/%E9%82%BE%E5%AE%AA%E5%85%AC"}]'::jsonb, '宪公', NULL, '邾子琐')
