VALUES ('zou-r14', '貜且', ARRAY[]::text[], '曹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '邾定公，邾文公之子，于文公卒后继位。传统年表以鲁文公十四年（前613）为其元年，记在位至前573年；邾文公迁绎后，邾国都城在绎。', '[{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"},{"label":"邾国故城（山东地情档案）","url":"https://shandong-chorography.org/database/a/section/70/article/91/"},{"label":"邾定公","url":"https://zh.wikipedia.org/wiki/%E9%82%BE%E5%AE%9A%E5%85%AC"}]'::jsonb, '定公', NULL, '邾定公')
