VALUES ('zou-r15', '牼', ARRAY[]::text[], '曹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '邾宣公，邾定公之子，后继位；传统年表系其在位于前572—前556年。关于其一名，传世版本有牼、瞷等异文。', '[{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"},{"label":"邾宣公","url":"https://zh.wikipedia.org/wiki/%E9%82%BE%E5%AE%A3%E5%85%AC"}]'::jsonb, '宣公', NULL, '邾宣公')
