VALUES ('zou-r18', '益', ARRAY[]::text[], '曹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '邾隐公，邾庄公之子。吴王夫差立其子革为君后，益一度失位；前473年复位，之后由另一子何继位。传世年表将其分作前506—前487年与前472—前471年两段。', '[{"label":"《左传·哀公八年》","url":"https://ctext.org/chun-qiu-zuo-zhuan/ai-gong-ba-nian/zhs"},{"label":"《左传·哀公二十四年》","url":"https://ctext.org/chun-qiu-zuo-zhuan/ai-gong-er-shi-si-nian/zhs"},{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"},{"label":"邾隐公","url":"https://zh.wikipedia.org/wiki/%E9%82%BE%E9%9A%90%E5%85%AC"}]'::jsonb, '隐公', NULL, '邾隐公')
