VALUES ('zou-r19', '革', ARRAY[]::text[], '曹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '邾桓公，邾隐公之子。吴王夫差拥立其为邾君，益复位后革奔越；《左传》记其被立、失位与出奔。', '[{"label":"《左传·哀公八年》","url":"https://ctext.org/chun-qiu-zuo-zhuan/ai-gong-ba-nian/zhs"},{"label":"邾桓公","url":"https://zh.wikipedia.org/wiki/%E9%82%BE%E6%A1%93%E5%85%AC"}]'::jsonb, '桓公', NULL, '邾桓公')
