VALUES ('zou-he', '何', ARRAY[]::text[], '曹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '邾子何，邾隐公之子，前471年由越人立为邾君。《左传·哀公二十四年》记其即位；其退位或卒年及后续继承次序无法由该条直接确定。', '[{"label":"《左传·哀公二十四年》","url":"https://ctext.org/chun-qiu-zuo-zhuan/ai-gong-er-shi-si-nian/zhs"},{"label":"邾子何","url":"https://zh.wikipedia.org/wiki/%E9%82%BE%E5%AD%90%E4%BD%95"}]'::jsonb, NULL, NULL, '邾子何')
