VALUES ('zou-kaogong', '考公', ARRAY[]::text[], '曹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '邾娄考公，传为邾隐公曾孙。《礼记·檀弓下》记徐君遣使来吊其丧；该记载未给出绝对年代，后世对其世代与年代有不同系年。', '[{"label":"《礼记·檀弓下》","url":"https://ctext.org/liji/tan-gong-xia/zhs"},{"label":"邾娄考公","url":"https://zh.wikipedia.org/wiki/%E9%82%BE%E5%A8%84%E8%80%83%E5%85%AC"}]'::jsonb, '考公', NULL, '邾娄考公')
