VALUES ('zou-jun-qing', '庆', ARRAY[]::text[], '曹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '邾君庆，春秋早期邾君。枣庄东江春秋墓地出土铜壶铭文称“邾君庆作秦妊礼壶”；现代邾器研究据器铭将其列入邾国君主世系。具体在位年份未考。', '[{"label":"冯峰：《说“醴壶”》（北京大学中国考古学研究中心）","url":"https://csca.pku.edu.cn/info/1018/1207.htm"},{"label":"张海：《邾器与两周邾邦史事》","url":"https://www.sohu.com/a/469705297_121124388"},{"label":"邾国君主世系图（据《春秋释例》等）","url":"https://zh.wikipedia.org/wiki/邾國君主世系圖"}]'::jsonb, NULL, NULL, '邾君庆')
