VALUES ('zou-state', '邹', ARRAY['邹国','邾国','邾娄'], 'cn', 'east_asia', -1046, 1, NULL, 'year', -256, 12, NULL, 'approximate_year', -12540, -3049, 'ochre', NULL, NULL, '周代曹姓诸侯国，春秋称邾或邾娄，战国至孟子时称邹。文公于前614年迁都绎并同年去世；楚灭邹的年代依晚战国通行说，具体年份有异说。早期传世世系及战国晚期君主的部分世次、在位年代存在资料局限；插值坐标仅用于时间轴定位，不表示已证实的在位年月或时长。')
